std::string inflate_bounded(const std::string&input){std::string out(64*1024*1024,'\0');uLongf n=out.size();if(uncompress((Bytef*)out.data(),&n,(const Bytef*)input.data(),input.size())!=Z_OK)throw std::runtime_error("bounded zlib");out.resize(n);return out;}
uint64_t hash_double(uint64_t h,double value){unsigned char b[8];std::memcpy(b,&value,8);for(auto x:b){h^=x;h*=1099511628211ull;}return h;}
void component(const std::string&input,const std::string&stem,std::ofstream&manifest,int frame,int laser,int ret,const std::string&kind){auto bytes=inflate_bounded(input);waymo::open_dataset::DeltaEncodedData d;if(!d.ParseFromString(bytes))throw std::runtime_error("delta protobuf");known(d);auto&m=d.metadata();if(m.shape_size()!=3||m.quant_precision_size()!=m.shape(2))throw std::runtime_error("metadata");uint64_t total=1;for(auto dim:m.shape()){if(dim<=0||dim>65535)throw std::runtime_error("dimension");total*=dim;}if(total>32*1024*1024)throw std::runtime_error("dense cap");for(auto p:m.quant_precision())if(!std::isfinite(p)||p<=0)throw std::runtime_error("precision");uint64_t coverage=0,ones=0;for(int i=0;i<d.mask_size();i++){coverage+=d.mask(i);if(i%2==0)ones+=d.mask(i);}if(coverage!=total||ones!=uint64_t(d.residual_size()))throw std::runtime_error("mask/residual coverage");std::ofstream masks(stem+".mask.bin",std::ios::binary),residuals(stem+".residual.bin",std::ios::binary);for(auto x:d.mask())masks.write((char*)&x,4);for(auto x:d.residual())residuals.write((char*)&x,8);std::ofstream meta(stem+".json");meta.precision(17);meta<<"{\"shape\":[";for(int i=0;i<3;i++)meta<<(i?",":"")<<m.shape(i);meta<<"],\"precision\":[";for(int i=0;i<m.quant_precision_size();i++)meta<<(i?",":"")<<m.quant_precision(i);meta<<"]}";
int64_t running=0;int index=0;uint64_t flat=0,positive=0,h=14695981039346656037ull;for(int run=0;run<d.mask_size();run++)for(uint32_t j=0;j<d.mask(run);j++){int64_t integer=0;if(run%2==0){auto residual=d.residual(index++);if((residual>0&&running>std::numeric_limits<int64_t>::max()-residual)||(residual<0&&running<std::numeric_limits<int64_t>::min()-residual))throw std::runtime_error("integer overflow");running+=residual;integer=running;}int channel=flat/(uint64_t(m.shape(0))*m.shape(1));double value=double(integer)*double(m.quant_precision(channel));if(!std::isfinite(value))throw std::runtime_error("nonfinite decoded");if(channel==0&&value>0)positive++;h=hash_double(h,value);flat++;}manifest<<frame<<'\t'<<laser<<'\t'<<ret<<'\t'<<kind<<'\t'<<std::filesystem::path(stem).filename().string()<<'\t'<<total<<'\t'<<positive<<'\t'<<h<<'\n';}
int main(int argc,char**argv){try{if(argc!=3)throw std::runtime_error("args");std::ifstream f(argv[1],std::ios::binary);auto n=std::filesystem::file_size(argv[1]);if(n>64*1024*1024)throw std::runtime_error("source cap");auto data=read(f,n);waymo::open_dataset::Scenario s;if(!s.ParseFromString(data))throw std::runtime_error("scenario");known(s);if(s.compressed_frame_laser_data_size()!=s.current_time_index()+1)throw std::runtime_error("causal sensor count");std::ofstream manifest(std::string(argv[2])+"/components.tsv");manifest<<"frame\tlaser\treturn\tkind\tstem\tvalues\tpositive_channel0\tchannel_major_float64_fnv1a\n";int count=0;for(int i=0;i<s.compressed_frame_laser_data_size();i++){std::set<int> ids;for(auto&laser:s.compressed_frame_laser_data(i).lasers()){if(!ids.insert(laser.name()).second)throw std::runtime_error("duplicate laser");for(int ret=1;ret<=2;ret++){const auto&r=ret==1?laser.ri_return1():laser.ri_return2();std::string stem=std::string(argv[2])+"/"+std::to_string(i)+"-"+std::to_string(laser.name())+"-"+std::to_string(ret);if(!r.range_image_delta_compressed().empty()){component(r.range_image_delta_compressed(),stem+"-range",manifest,i,laser.name(),ret,"range");count++;}if(!r.range_image_pose_delta_compressed().empty()){component(r.range_image_pose_delta_compressed(),stem+"-pose",manifest,i,laser.name(),ret,"pose");count++;}}}}std::cout<<"COMPONENTS "<<s.scenario_id()<<" "<<count<<"\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
